package ai.ragflow4j.ragflow;

import static org.junit.jupiter.api.Assertions.*;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

class WordNetTest {
    @Test
    void everySynsetFieldMatchesOriginalGoOracle() throws Exception {
        // Generated by executing the original wordnet.go at e4bd080 against the pinned resources.
        var mapper = new ObjectMapper();
        var wordnet = new WordNet(NativeTokenizer.defaultResourcePath().resolve("wordnet"));
        try (var stream = getClass().getResourceAsStream("/ragflow/wordnet-go-golden.json")) {
            assertNotNull(stream);
            var expectedByWord = mapper.readTree(stream);
            var fields = expectedByWord.fields();
            while (fields.hasNext()) {
                var entry = fields.next();
                var actual = wordnet.synsets(entry.getKey(), "");
                assertEquals(entry.getValue().size(), actual.size(), entry.getKey());
                for (int i = 0; i < actual.size(); i++) {
                    var expected = entry.getValue().get(i);
                    var synset = actual.get(i);
                    assertEquals(expected.path("Name").asText(), synset.name());
                    assertEquals(expected.path("POS").asText(), synset.pos());
                    assertEquals(expected.path("Offset").asInt(), synset.offset());
                    assertEquals(expected.path("Definition").asText(), synset.definition());
                    assertEquals(expected.path("Lemmas"), mapper.valueToTree(synset.lemmas()));
                    if (expected.path("Examples").isNull()) assertTrue(synset.examples().isEmpty());
                    else assertEquals(expected.path("Examples"), mapper.valueToTree(synset.examples()));
                }
            }
        }
    }
}
